import disclaimer from '../../config/text/disclaimer.txt?raw'
import { IconAlert } from '../ui/icons'

// The text is frozen spec data (section 7), generated by scripts/extract-spec-text.mjs. Never retype it here.
// The leading warning emoji is kept in the DOM inside a hidden span so the string stays byte-exact;
// an outline triangle is drawn instead, in line with the "no emoji in UI chrome" rule.
const LEADING_GLYPH = /^\p{Extended_Pictographic}\uFE0F?\s*/u
const text = disclaimer.trim()
const glyph = text.match(LEADING_GLYPH)?.[0] ?? ''
const body = text.slice(glyph.length)

export function DisclaimerBanner() {
  return (
    <section
      aria-labelledby="disclaimer-title"
      className="border-b-2 border-warn-edge bg-warn-bg text-warn-ink"
      data-testid="disclaimer"
    >
      <div className="mx-auto flex max-w-[105rem] items-start gap-3 px-4 py-2.5 md:px-6 xl:px-10">
        <IconAlert className="mt-0.5 shrink-0" width={18} height={18} />
        <div className="text-small">
          <h2 id="disclaimer-title" className="inline text-small font-bold">
            Disclaimer{' '}
          </h2>
          <p className="inline">
            {glyph && <span hidden>{glyph}</span>}
            <span data-testid="disclaimer-text">{body}</span>
          </p>
        </div>
      </div>
    </section>
  )
}
